"""CLI for the expense splitter."""

from __future__ import annotations

import json
from datetime import date
from decimal import Decimal
from pathlib import Path

import click

from .math import compute_balances, settle_up
from .models import Expense, Group
from .storage import load_group, save_group

DATA_DIR = Path(click.get_app_dir("expense_splitter"))


def _group_path(name: str) -> Path:
    """Return the file path for a group."""
    return DATA_DIR / f"{name}.json"


def _load_or_create(ctx, name):
    """Load an existing group or create a new one if it doesn't exist."""
    p = _group_path(name)
    if p.exists():
        return load_group(p), p
    g = Group(name=name)
    save_group(g, p)
    return g, p


def _save(ctx, group, path):
    """Save a group to disk."""
    save_group(group, path)


@click.group()
def cli():
    """Expense Splitter — track and settle shared expenses."""
    pass


# ── create ────────────────────────────────────────────────────────────────
@cli.command("create")
@click.argument("name")
@click.option("--member", "-m", multiple=True, help="Add a member at creation time.")
def cmd_create(name: str, member: tuple[str, ...]):
    """Create a new expense group."""
    p = _group_path(name)
    if p.exists():
        click.echo(f"Group '{name}' already exists.", err=True)
        raise SystemExit(1)
    g = Group(name=name, members=list(member))
    save_group(g, p)
    click.echo(f"Created group '{name}'.")


# ── add ───────────────────────────────────────────────────────────────────
@cli.command("add")
@click.argument("group_name")
@click.option("--payer", "-p", required=True, help="Who paid.")
@click.option("--amount", "-a", type=click.FLOAT, required=True, help="Amount spent.")
@click.option("--description", "-d", default="", help="Description of the expense.")
@click.option(
    "--split-among",
    "-s",
    multiple=True,
    help="Who to split among (repeat for each person; defaults to all members).",
)
def cmd_add(group_name: str, payer: str, amount: float, description: str, split_among: tuple[str, ...]):
    """Add an expense to a group."""
    g, p = _load_or_create(None, group_name)

    if payer not in g.members:
        click.echo(f"Payer '{payer}' is not a member of '{group_name}'.", err=True)
        raise SystemExit(1)

    if split_among:
        for s in split_among:
            if s not in g.members:
                click.echo(f"'{s}' is not a member of '{group_name}'.", err=True)
                raise SystemExit(1)
        members = list(split_among)
    else:
        members = list(g.members)

    expense = Expense(
        payer=payer,
        amount=amount,
        description=description,
        date=date.today(),
        split_among=members,
    )
    g.expenses.append(expense)
    save_group(g, p)
    click.echo(f"Added expense: {payer} paid {amount:.2f} for '{description or 'no description'}'.")


# ── list ──────────────────────────────────────────────────────────────────
@cli.command("list")
@click.argument("group_name")
def cmd_list(group_name: str):
    """List all expenses in a group."""
    g, _ = _load_or_create(None, group_name)

    if not g.expenses:
        click.echo(f"No expenses in '{group_name}'.")
        return

    for i, e in enumerate(g.expenses, 1):
        split_str = ", ".join(e.split_among) if e.split_among else "(none)"
        click.echo(
            f"{i}. {e.date} | {e.payer} paid {e.amount:.2f} | "
            f"split: [{split_str}] | {e.description or ''}"
        )


# ── balances ──────────────────────────────────────────────────────────────
@cli.command("balances")
@click.argument("group_name")
def cmd_balances(group_name: str):
    """Show the current balance for each member."""
    g, _ = _load_or_create(None, group_name)

    expenses_list = [
        (e.payer, e.amount, e.split_among) for e in g.expenses
    ]
    balances = compute_balances(g.members, expenses_list)

    if not balances:
        click.echo(f"No members in '{group_name}'.")
        return

    for member, bal in sorted(balances.items()):
        sign = "+" if bal >= 0 else ""
        status = "is owed" if bal > 0 else ("owes" if bal < 0 else "settled")
        click.echo(f"{member}: {sign}{bal:.2f} ({status})")


# ── settle-up ─────────────────────────────────────────────────────────────
@cli.command("settle-up")
@click.argument("group_name")
def cmd_settle_up(group_name: str):
    """Show the minimal set of transfers to settle all debts."""
    g, _ = _load_or_create(None, group_name)

    expenses_list = [
        (e.payer, e.amount, e.split_among) for e in g.expenses
    ]
    balances = compute_balances(g.members, expenses_list)
    transfers = settle_up(balances)

    if not transfers:
        click.echo("Everyone is already settled up.")
        return

    for frm, to, amt in transfers:
        click.echo(f"{frm} -> {to}: {amt:.2f}")


# ── delete ────────────────────────────────────────────────────────────────
@cli.command("delete")
@click.argument("group_name")
def cmd_delete(group_name: str):
    """Delete a group and all its data."""
    p = _group_path(group_name)
    if not p.exists():
        click.echo(f"Group '{group_name}' does not exist.", err=True)
        raise SystemExit(1)
    p.unlink()
    click.echo(f"Deleted group '{group_name}'.")


# ── edit ──────────────────────────────────────────────────────────────────
@cli.command("edit")
@click.argument("group_name")
@click.option("--add-member", "-am", help="Add a member to the group.")
@click.option("--remove-member", "-rm", help="Remove a member from the group.")
def cmd_edit(group_name: str, add_member: str | None, remove_member: str | None):
    """Edit a group's membership."""
    g, p = _load_or_create(None, group_name)

    if add_member:
        if add_member in g.members:
            click.echo(f"'{add_member}' is already a member.", err=True)
            raise SystemExit(1)
        g.members.append(add_member)
        save_group(g, p)
        click.echo(f"Added '{add_member}' to group '{group_name}'.")

    if remove_member:
        if remove_member not in g.members:
            click.echo(f"'{remove_member}' is not a member.", err=True)
            raise SystemExit(1)
        g.members.remove(remove_member)
        save_group(g, p)
        click.echo(f"Removed '{remove_member}' from group '{group_name}'.")

    if not add_member and not remove_member:
        click.echo("Use --add-member or --remove-member to edit the group.")


# ── export ────────────────────────────────────────────────────────────────
@cli.command("export")
@click.argument("group_name")
@click.option(
    "--format",
    "fmt",
    type=click.Choice(["json", "csv"]),
    default="json",
    help="Export format.",
)
def cmd_export(group_name: str, fmt: str):
    """Export group data in JSON or CSV format."""
    g, _ = _load_or_create(None, group_name)

    if fmt == "json":
        click.echo(g.to_json(indent=2))
    elif fmt == "csv":
        import csv
        import io

        buf = io.StringIO()
        writer = csv.writer(buf)
        writer.writerow(["date", "payer", "amount", "description", "split_among"])
        for e in g.expenses:
            writer.writerow(
                [
                    e.date.isoformat(),
                    e.payer,
                    f"{e.amount:.2f}",
                    e.description,
                    ";".join(e.split_among),
                ]
            )
        click.echo(buf.getvalue().rstrip())

"""Data models for the expense splitter."""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from datetime import date, datetime
from typing import Any


def _date_serializer(obj: Any) -> str:
    """JSON serializer for objects not serializable by default."""
    if isinstance(obj, (datetime, date)):
        return obj.isoformat()
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


@dataclass
class Expense:
    """A single expense within a group."""

    payer: str
    amount: float
    description: str = ""
    date: date = field(default_factory=date.today)
    split_among: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        d = asdict(self)
        if isinstance(d.get("date"), (datetime, date)):
            d["date"] = d["date"].isoformat()
        return d

    def to_json(self, **kwargs: Any) -> str:
        return json.dumps(self.to_dict(), default=_date_serializer, **kwargs)

    @classmethod
    def from_dict(cls, data: dict) -> Expense:
        if "date" in data and isinstance(data["date"], str):
            data = {**data, "date": date.fromisoformat(data["date"])}
        return cls(**data)

    @classmethod
    def from_json(cls, raw: str) -> Expense:
        return cls.from_dict(json.loads(raw))


@dataclass
class Group:
    """A group of people sharing expenses."""

    name: str
    members: list[str] = field(default_factory=list)
    expenses: list[Expense] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "members": self.members,
            "expenses": [e.to_dict() for e in self.expenses],
        }

    def to_json(self, **kwargs: Any) -> str:
        return json.dumps(self.to_dict(), default=_date_serializer, **kwargs)

    @classmethod
    def from_dict(cls, data: dict) -> Group:
        expenses = [Expense.from_dict(e) for e in data.get("expenses", [])]
        return cls(
            name=data["name"],
            members=data.get("members", []),
            expenses=expenses,
        )

    @classmethod
    def from_json(cls, raw: str) -> Group:
        return cls.from_dict(json.loads(raw))
